INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(42711, 'Jeremiah 27:6', 'Jeremiah', 27, 6, 'خو زۀ به اوس ستاسو ټول مُلکونه خپل خِدمت کوونکى نبوکدنضر د بابل بادشاه ته حواله کړم، تر دې چې زۀ به ځنګلى ځناور هم د دۀ تابعدار کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_6.mp3', '', 1761754199, 1761754199),
(42712, 'Jeremiah 27:7', 'Jeremiah', 27, 7, 'ټول قومونه به د هغۀ خِدمت وکړى، او د هغۀ د زوئ او د نمسى به تر هغې پورې خِدمت کوى ترڅو چې د هغۀ د مُلک د ختمېدو دپاره مقرر شوے وخت نۀ وى راغلے. نو بيا به نور ډېر قومونه او لوئ بادشاهان راشى او بابليان به خپل غلامان جوړ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_7.mp3', '', 1761754199, 1761754199),
(42713, 'Jeremiah 27:8', 'Jeremiah', 27, 8, 'مالِک خُدائ داسې فرمائى چې، کۀ چرې يو قوم يا بادشاهت د نبوکدنضر يعنې د بابل د بادشاه د خِدمت نه اِنکار وکړى او يا خپل څټ د هغۀ د جغ لاندې نۀ کړى، نو زۀ به بيا په هغه قوم جنګ، قحط او وبا را نازله کړم، ترڅو چې بابليانو هغه قبضه کړے نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_8.mp3', '', 1761754199, 1761754199),
(42714, 'Jeremiah 27:9', 'Jeremiah', 27, 9, 'نو بيا خپلو دروغژنو نبيانو، فالګرو، د خوب تعبير کوونکو، خپل قسمت معلومونکو او جادوګرو ته غوږ مۀ نيسئ، څوک چې تاسو ته وائى چې تاسو به د بابل د بادشاه خِدمت نۀ کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_9.mp3', '', 1761754199, 1761754199),
(42715, 'Jeremiah 27:10', 'Jeremiah', 27, 10, 'هغوئ تاسو ته د دروغو نبوت کوى او په دې خبرو به تاسو د خپل مُلک نه لرې وشړلے شئ، زۀ به تاسو خوارۀ وارۀ کړم او تاسو به تباه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_10.mp3', '', 1761754199, 1761754199),
(42716, 'Jeremiah 27:11', 'Jeremiah', 27, 11, 'خو کۀ کوم يو قوم هم خپل څټ د بابل بادشاه د جغ لاندې ښکته کړى او د هغۀ خِدمت وکړى، نو زۀ به دا قوم په خپله زمکه باندې پرېږدم چې هغه وکَرى او هلته اوسيږى.“ دا د مالِک خُدائ وينا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_11.mp3', '', 1761754199, 1761754199),
(42717, 'Jeremiah 27:12', 'Jeremiah', 27, 12, 'ما هم دا پېغام د يهوداه بادشاه صدقياه ته ورکړو. ما ورته ووئيل، ”خپل څټونه د بابل بادشاه جغ ته ښکته کړئ، د هغۀ او د هغۀ د خلقو خِدمت وکړئ، نو تاسو به ژوندى پاتې شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_12.mp3', '', 1761754199, 1761754199),
(42718, 'Jeremiah 27:13', 'Jeremiah', 27, 13, 'نو بيا ولې تۀ او ستا عوام دې په هغه جنګ، قحط يا وبا مړۀ شى په کومو چې مالِک خُدائ هر هغه قوم يروى څوک چې د بابل د بادشاه د خِدمت نه اِنکار کوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_13.mp3', '', 1761754199, 1761754199),
(42719, 'Jeremiah 27:14', 'Jeremiah', 27, 14, 'د دروغژنو نبيانو خبرو ته غوږ مۀ نيسئ څوک چې تاسو ته وائى چې د بابل د بادشاه خِدمت به نۀ کوئ، ځکه چې هغوئ تاسو ته دروغ وائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_14.mp3', '', 1761754199, 1761754199),
(42720, 'Jeremiah 27:15', 'Jeremiah', 27, 15, 'مالِک خُدائ په خپله فرمائيلى دى چې، هغوئ ما نۀ دى درلېږلى. هغوئ زما په نوم د دروغو نبوت کوى. نو ځکه زۀ به تاسو د خپل مُلک نه وشړم، نو تاسو او هغه نبيان دواړه به هلاک شئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_15.mp3', '', 1761754199, 1761754199),
(42721, 'Jeremiah 27:16', 'Jeremiah', 27, 16, 'نو بيا ما اِمامانو ته ووئيل چې، ”دا هغه څۀ دى چې مالِک خُدائ فرمائيلى دى، هغه نبيانو ته غوږ مۀ نيسئ چې څوک داسې وائى چې د خُدائ پاک د کور مقدس څيزونه به ډېر زر د بابل نه راواپس شى. هغوئ تاسو ته د دروغو پېشګويانې کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_16.mp3', '', 1761754199, 1761754199),
(42722, 'Jeremiah 27:17', 'Jeremiah', 27, 17, 'هغوئ ته غوږ مۀ نيسئ، د بابل د بادشاه خِدمت کوئ، نو تاسو به ژوندى پاتې شئ. نو بيا دې ولې دا ښار تباه او په کنډرو بدل شى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_17.mp3', '', 1761754199, 1761754199),
(42723, 'Jeremiah 27:18', 'Jeremiah', 27, 18, 'کۀ چرې هغوئ په رښتيا سره پېغمبران وى او د مالِک خُدائ د خوا نه ورته کلام ورکړے شوے وى نو بيا دې هغوئ ما ته چې مالِک خُدائ ربُ الافواج يم سوال او مِنت وکړى چې زۀ هغه پاتې شوى مقدس څيزونه بابل ته پرې نۀ ږدم چې هغوئ يوسى. او چې هغه په يروشلم کښې د مالِک خُدائ په کور او د يهوداه بادشاه په محل کښې پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_18.mp3', '', 1761754199, 1761754199),
(42724, 'Jeremiah 27:19', 'Jeremiah', 27, 19, 'نو مالِک خُدائ، ربُ الافواج د هغه څيزونو په حقله وفرمائيل کوم چې په يروشلم کښې پاتې وُو لکه د زېړو ستنې او د زېړو ډيګۍ، او د اوبو راوړلو ګاډۍ او نور سامانونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_19.mp3', '', 1761754199, 1761754199),
(42725, 'Jeremiah 27:20', 'Jeremiah', 27, 20, 'دا هم هغه پاتې شوى څيزونه دى کله چې نبوکدنضر بادشاه د يهوداه بادشاه، د يهويقيم زوئ يهوياکين او د يهوداه او يروشلم مشران سپين روبى ټول بابل ته بوتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_20.mp3', '', 1761754199, 1761754199),
(42726, 'Jeremiah 27:21', 'Jeremiah', 27, 21, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى هغه څيزونو په حقله کوم چې د مالِک خُدائ په کور کښې پاتې دى او د يهوداه او په يروشلم او د بادشاه په محل کښې پاتې دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_21.mp3', '', 1761754199, 1761754199),
(42727, 'Jeremiah 27:22', 'Jeremiah', 27, 22, 'دا سامانونه به بابل ته يوړے شى او دا به زما د راتلو د ورځې پورې هلته وى، مالِک خُدائ داسې فرمائى چې، نو بيا به زۀ دا ټول سامان واپس راوړم او په دې ځائ کښې به يې ولګوم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah27_verse_22.mp3', '', 1761754199, 1761754199),
(42728, 'Psalms 72:1', 'Psalms', 72, 1, 'خدایه ورکړه ته پاچا ته خپل انصاف د پاچا زوی ته په برخه عدالت کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_1.mp3', '', 1761754199, 1761754199),
(42729, 'Psalms 72:2', 'Psalms', 72, 2, 'ترڅو ستا قوم باندې په عدالت سره حکومت وکاندي او د بې‌وزله سره وکړي انصاف', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_2.mp3', '', 1761754199, 1761754199),
(42730, 'Psalms 72:3', 'Psalms', 72, 3, 'غرونه به راوړي سوکالي خلکو ته غونډۍ به راوړي د نېکۍ مېوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_3.mp3', '', 1761754199, 1761754199),
(42731, 'Psalms 72:4', 'Psalms', 72, 4, 'د قوم غریبو سره وبه کړي هغه انصاف محتاجو خلکو ته به ورکړي نجات او ظالمان به رېزمرېز کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_4.mp3', '', 1761754199, 1761754199),
(42732, 'Psalms 72:5', 'Psalms', 72, 5, 'څو چې لمر او سپوږمۍ وي په دې جهان تل ترتله د یو نسل نه تر بله خدایه ستا ولس به ستا ځینې وېریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_5.mp3', '', 1761754199, 1761754199),
(42733, 'Psalms 72:6', 'Psalms', 72, 6, 'پاچا به اوسي د باران په شان چې اوري په پټیو باندې لکه شېبه باران چې ځمکې ته اوبه ورکوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_6.mp3', '', 1761754199, 1761754199),
(42734, 'Psalms 72:7', 'Psalms', 72, 7, 'عادلان به وده وکړي د هغه دوران کې ترڅو سپوږمۍ وي په اسمان کې وي به سوله هلته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_7.mp3', '', 1761754199, 1761754199),
(42735, 'Psalms 72:8', 'Psalms', 72, 8, 'وبه رسیږي پاچاهي د هغه د ختیځې بحیرې نه تر لوېدیځې پورې او د فرات له سیند نه د دنیا تر بله سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_8.mp3', '', 1761754199, 1761754199),
(42736, 'Psalms 72:9', 'Psalms', 72, 9, 'د بیابان خلک به یې په مخکې په سجده پرېوځي دښمنان به یې راپرېوځي پړمخې خاورو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_9.mp3', '', 1761754199, 1761754199),
(42737, 'Psalms 72:10', 'Psalms', 72, 10, 'پاچاهان به د ترشیش او جزیرو ورته راوړي باجونه ورته راوړي به سوغاتونه د شیبا او د سیبا پاچاهان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_10.mp3', '', 1761754199, 1761754199),
(42738, 'Psalms 72:11', 'Psalms', 72, 11, 'ټول پاچاهان به یې په مخکې خپل سرونه ټیټ کړي او ټول قومونه به یې کاندي خدمت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_11.mp3', '', 1761754199, 1761754199),
(42739, 'Psalms 72:12', 'Psalms', 72, 12, 'چې غریب خلک ورنه کله هم کومک وغواړي ورته نجات ورکوي او کوي مرسته د غریبو او بې‌کسو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_12.mp3', '', 1761754199, 1761754199),
(42740, 'Psalms 72:13', 'Psalms', 72, 13, 'په ضعیفانو او محتاجو باندې رحم کوي څوک چې محتاج وي هغه یې ژوند بچ کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_13.mp3', '', 1761754199, 1761754199),
(42741, 'Psalms 72:14', 'Psalms', 72, 14, 'خلاصوي هغوی د ظلم او د جبر ځکه چې وینه یې قیمتي ده ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_14.mp3', '', 1761754199, 1761754199),
(42742, 'Psalms 72:15', 'Psalms', 72, 15, 'عمر دې زیات وي د شاه! ورته نصیب دې شي طلا د شیبا دعا د خلکو دې وي تل ورسره برکتونه دې د خدای وي همېشه ورسره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_15.mp3', '', 1761754199, 1761754199),
(42743, 'Psalms 72:16', 'Psalms', 72, 16, 'وي دې په ځمکه د غلو پرېماني په حاصلاتو دې تپې پټې وي وي دې مېوې یې د لبنان په شانتې ښارونه ډک دې وي د خلکو ځینې لکه چې ځمکې وي واښو نه ډکې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_16.mp3', '', 1761754199, 1761754199),
(42744, 'Psalms 72:17', 'Psalms', 72, 17, 'هېڅکله هېر دې نه شي نوم د هغه وي برقرار دې لکه لمر په شان شهرت د هغه برکت دې ورته ورکړل شي ټولو قومونو ته د خدای له خوا نه هغوی به هغه مبارک وبولي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_17.mp3', '', 1761754199, 1761754199),
(42745, 'Psalms 72:18', 'Psalms', 72, 18, 'ثنا او صفت دې وي د اسراییلو څښتن خدای ته یوازې هغه دی چې کړي دا عجیبه کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_18.mp3', '', 1761754199, 1761754199),
(42746, 'Psalms 72:19', 'Psalms', 72, 19, 'د جلال ډک نوم د هغه دې مبارک وي همېش ډک دې شي ټول جهان د ده په جلال امین! امین!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_19.mp3', '', 1761754199, 1761754199),
(42747, 'Psalms 72:20', 'Psalms', 72, 20, 'د یسي د زوی داود دعاګانې په همدې ځای کې پای ته ورسېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms72_verse_20.mp3', '', 1761754199, 1761754199),
(42748, 'Joshua 11:1', 'Joshua', 11, 1, 'کله چې د اسراییلو د بریالیتوب خبر د حاصور پاچا یابین ته ورسېده، هغه د مادون پاچا یوباب او د شمرون او اخشاف پاچاهانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_1.mp3', '', 1761754199, 1761754199),
(42749, 'Joshua 11:2', 'Joshua', 11, 2, 'او هغو پاچاهانو ته پیغام ولېږه چې د شمال په غرنۍ سیمه کې، د اردن په دره کې، د جلیل د بحیرې په جنوب کې، د غرونو په لمنو کې او دور ته نژدې په غونډیو باندې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_2.mp3', '', 1761754199, 1761754199),
(42750, 'Joshua 11:3', 'Joshua', 11, 3, 'همدارنګه هغه د کنعانیانو پاچاهانو ته چې د اردن د سیند په دواړو خواوو کې اوسېدل، د اموریانو، حیتیانو، فرزیانو او یبوسیانو پاچاهانو ته چې په غرنۍ سیمه کې اوسېدل او د هغو حویانو پاچاهانو ته هم پیغام ورولېږه چې د حرمون د غره په لمنو کې د مصفه په خاوره کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_3.mp3', '', 1761754199, 1761754199),
(42751, 'Joshua 11:4', 'Joshua', 11, 4, 'هغوی د خپلو ټولو عسکرو سره راغلل. هغه یو لوی لښکر ؤ او د بحیرې د شګو په شان ډېر وو. هغوی ډېر زیات اسونه او جنګي ګاډۍ هم درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_4.mp3', '', 1761754199, 1761754199),
(42752, 'Joshua 11:5', 'Joshua', 11, 5, 'دا ټول پاچاهان سره راټول شول او د میروم د خوړ سره یې کمپ جوړ کړ. هلته هغوی خپل ځواکونه سره یوځای کړل چې د اسراییلو په وړاندې وجنګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_5.mp3', '', 1761754199, 1761754199),
(42753, 'Joshua 11:6', 'Joshua', 11, 6, 'څښتن یوشع ته وویل: «د هغوی څخه مه وېرېږه، ځکه چې زه څښتن به هغوی ټول ووژنم. سبا دا وخت به هغوی ټول مړه وي. له جګړې څخه وروسته د هغوی اسونه ګوډ کړئ او جنګي ګاډۍ یې وسوځوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_6.mp3', '', 1761754199, 1761754199),
(42754, 'Joshua 11:7', 'Joshua', 11, 7, 'نو یوشع او د هغه ټول لښکر په هغوی باندې د میروم د خوړ تر څنګ ناڅاپه حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_7.mp3', '', 1761754199, 1761754199),
(42755, 'Joshua 11:8', 'Joshua', 11, 8, 'څښتن اسراییلیان په هغوی باندې بریالي کړل. اسراییلیانو په هغوی باندې حمله وکړه او په شمال کې یې تر مسرفوت مایم او لوی صیدون او په ختیځ کې د مصفه تر درې پورې تعقیب کړل. جګړه تر هغه وخته پورې روانه وه، ترڅو چې د دښمن له خوا هېڅوک ژوندی پاتې نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_8.mp3', '', 1761754199, 1761754199),
(42756, 'Joshua 11:9', 'Joshua', 11, 9, 'یوشع د هغوی سره هماغه شان کار وکړ څنګه چې څښتن هغه ته حکم کړی ؤ. هغه د هغوی اسونه ګوډ کړل او د هغوی جنګي ګاډۍ یې وسوځولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_9.mp3', '', 1761754199, 1761754199),
(42757, 'Joshua 11:10', 'Joshua', 11, 10, 'یوشع بېرته راوګرځېد، هغه د حاصور ښار ونیوه او د هغه ځای پاچا یې وواژه. (په هغه وخت کې نورې پاچاهۍ چې پورته ورڅخه یادونه وشوه، د حاصور د پاچا تر واکمنۍ لاندې وې.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_10.mp3', '', 1761754199, 1761754199),
(42758, 'Joshua 11:11', 'Joshua', 11, 11, 'هغوی هلته ټول خلک ووژل. هېڅوک ژوندی پاتې نه شو او ښار یې وسوځاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_11.mp3', '', 1761754199, 1761754199),
(42759, 'Joshua 11:12', 'Joshua', 11, 12, 'یوشع هغه ټول ښارونه د هغو د پاچاهانو سره ونیول او ټول یې ووژل. لکه څنګه چې د څښتن خدمتګار موسی امر کړی ؤ، یوشع هغوی په پوره توګه له منځه یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_12.mp3', '', 1761754199, 1761754199),
(42760, 'Joshua 11:13', 'Joshua', 11, 13, 'خو بیاهم، اسراییلیانو د هغو ښارونو څخه چې په غونډیو باندې ودان شوي وو هېڅ کوم ښار ونه سوځاوه، پرته له حاصور څخه چې یوشع هغه وسوځاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_13.mp3', '', 1761754199, 1761754199),
(42761, 'Joshua 11:14', 'Joshua', 11, 14, 'د اسراییلو خلکو د دې ښارونو څخه ټول قیمتي شیان او څاروي یووړل او د ځانونو دپاره یې وساتل. خو هغوی ټول خلک ووژل، هېڅوک هم ژوندی پاتې نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_14.mp3', '', 1761754199, 1761754199),
(42762, 'Joshua 11:15', 'Joshua', 11, 15, 'څښتن خپل خدمتګار موسی ته حکمونه ورکړي وو، موسی هغه یوشع ته ورکړل او یوشع هغه سرته ورسول. یوشع هغه ټول کارونه تر سره کړل چې څښتن په موسی باندې د هغو حکم کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_15.mp3', '', 1761754199, 1761754199),
(42763, 'Joshua 11:16', 'Joshua', 11, 16, 'نو یوشع دغه ټوله خاوره ونیوله: غرنۍ سیمه، د غرونو لوېدیځې لمنې، شمال او جنوب دواړه، د جوشن ټوله سیمه، ټوله جنوبي دښته او د اردن دره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_16.mp3', '', 1761754199, 1761754199),
(42764, 'Joshua 11:21', 'Joshua', 11, 21, 'په هغه وخت کې یوشع عناقیان چې لوړ قدونه یې درلودل او په حبرون، دبیر، عناب او د یهودا او اسراییلو په پاتې ټولو غرنیو سیمو کې اوسېدل هم له منځه یووړل. یوشع هغوی د خپلو ښارونو سره بیخي له منځه یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_21.mp3', '', 1761754199, 1761754199),
(42765, 'Joshua 11:22', 'Joshua', 11, 22, 'د عناقیانو څخه هېڅوک د اسراییلیانو په خاوره کې پاتې نه شو، یوازې په غزه، جت او اشدود کې ځینې خلک ژوندي پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_22.mp3', '', 1761754199, 1761754199),
(42766, 'Joshua 11:23', 'Joshua', 11, 23, 'څنګه چې څښتن موسی ته لارښوونه کړې وه، یوشع ټوله خاوره ونیوله او هغه یې اسراییلیانو ته د هغوی د خپل ملکیت په توګه ورکړه. هغه یې په څو برخو ووېشله، هرې قبیلې ته یوه برخه ورسېدله. په پای کې په هغه هېواد کې ارامي شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua11_verse_23.mp3', '', 1761754199, 1761754199),
(42767, 'Psalms 45:1', 'Psalms', 45, 1, 'څنګه چې زه دغه سندره جوړومه د پاچا دپاره راځي مې ذهن ته ښایسته او پارېدونکي الفاظ د ښه لیکونکي د قلم په شان ژبه زما شوله تیاره شعر ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_1.mp3', '', 1761754199, 1761754199),
(42768, 'Psalms 45:2', 'Psalms', 45, 2, 'ته د ټولو انسانانو نه ښایسته یې ستا د خولې خبرې دي د مرغلرو په څېر ځکه خدای تاته تل برکت درکړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_2.mp3', '', 1761754199, 1761754199),
(42769, 'Psalms 45:3', 'Psalms', 45, 3, 'ای جنګیالیه، توره وتړه د ملا څخه دې ته دې خپل شان او دبدبه وښایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_3.mp3', '', 1761754199, 1761754199),
(42770, 'Psalms 45:4', 'Psalms', 45, 4, 'خپلې لویۍ سره دې سپور شه چې بری ومومې د حقیقت او عاجزۍ او عدالت نه د دفاع دپاره! پرېږده ځواکمن لاس دې چې وښایي ستا لوی کارونه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_4.mp3', '', 1761754199, 1761754199),
(42771, 'Psalms 45:5', 'Psalms', 45, 5, 'غشي د ستا دي تېره ننوځي ستا د دښمنانو په زړه نابود قومونه ستا تر‌پښو لاندې دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_5.mp3', '', 1761754199, 1761754199),
(42772, 'Psalms 45:6', 'Psalms', 45, 6, 'تاته چې خدای کوم پاچاهي درکړې دوام به وکړي تر ابده پورې او کړې به حکومت په خپلو خلکو باندې د انصاف له مخې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_6.mp3', '', 1761754199, 1761754199),
(42773, 'Psalms 45:7', 'Psalms', 45, 7, 'ته خوښوې عدالت او کرکه کوې له بدۍ په دې خاطر خدای، یعنې ستا خدای ته یې ستا د نورو ملګرو نه زیات مسح کړی یې د خوشحالۍ په تېلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_7.mp3', '', 1761754199, 1761754199),
(42774, 'Psalms 45:8', 'Psalms', 45, 8, 'ستا د کالیو نه خوشبوي راځي د مر کنډ، عود او دالچینۍ د عطرو رباب وهونکي خوشحال ساتي تا په داسې قصرو چې سینګار شوي دي د فیل په غاښو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_8.mp3', '', 1761754199, 1761754199),
(42775, 'Psalms 45:9', 'Psalms', 45, 9, 'ستا معززو ښځو کې دي د پاچاهانو لوڼې دا ستا د تخت په ښي لاس ده د اوفیر په سرو زرو خالصو سینګار شوې ملکه ولاړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_9.mp3', '', 1761754199, 1761754199),
(42776, 'Psalms 45:10', 'Psalms', 45, 10, 'ای شاهزادګۍ ونیسه غوږ زما بیان ته په غور ته دې خپل خلک او د پلار کور هېر کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_10.mp3', '', 1761754199, 1761754199),
(42777, 'Psalms 45:11', 'Psalms', 45, 11, 'نو په ښایست به پاچا ستا شوقمن شي هغه څښتن دی د ستا، نو اطاعت یې کوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_11.mp3', '', 1761754199, 1761754199),
(42778, 'Psalms 45:12', 'Psalms', 45, 12, 'تاته راوړي به سوغاتونه دا د صور خلک ستا نه به غواړي پېرزوینه دولتمن خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_12.mp3', '', 1761754199, 1761754199),
(42779, 'Psalms 45:13', 'Psalms', 45, 13, 'په ماڼۍ کې شاهزادګۍ څومره ښایسته ده! چې کالي یې دي جوړ شوي د سرو زرو له تارونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_13.mp3', '', 1761754199, 1761754199),
(42780, 'Psalms 45:14', 'Psalms', 45, 14, 'پاچا ته بیایي هغه په رنګارنګ لباس کې پېغلې نجونې سهېلۍ یې ورپسې دي هغوی به هم هغه ته راولي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_14.mp3', '', 1761754199, 1761754199),
(42781, 'Psalms 45:15', 'Psalms', 45, 15, 'هغوی به راشي په خوښۍ او خوشحالۍ سره شي به داخلې د پاچا ماڼۍ ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_15.mp3', '', 1761754199, 1761754199),
(42782, 'Psalms 45:16', 'Psalms', 45, 16, 'ای زما پاچا ته به زامن ولرې چې پاچاهان شي ستا نیکونو په څېر ټولې نړۍ باندې هغوی به حاکمان کړې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_16.mp3', '', 1761754199, 1761754199),
(42783, 'Psalms 45:17', 'Psalms', 45, 17, 'زه مشهور به کړم ستا نوم ټولو نسلونو کې قومونه وایي ستا ثنا به تر ابده پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms45_verse_17.mp3', '', 1761754199, 1761754199),
(42784, 'Proverbs 13:1', 'Proverbs', 13, 1, 'د حکمت خاوند د خپل پلار نصیحت قبلوي خو ملنډې وهونکی خپله ملامتیا نه مني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_1.mp3', '', 1761754199, 1761754199),
(42785, 'Proverbs 13:2', 'Proverbs', 13, 2, 'د ښه سړي د خولې له هوښیارو خبرو ښه خوند اخیستل کیږي خو د خاینانو زړونه د ظلم تږي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_2.mp3', '', 1761754199, 1761754199),
(42786, 'Proverbs 13:3', 'Proverbs', 13, 3, 'څوک چې ژبه په واک کې ساتي نو خپل ځان ساتي خو څوک چې بېځایه خبرې کوي نو خپل ځان تباه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_3.mp3', '', 1761754199, 1761754199),
(42787, 'Proverbs 13:4', 'Proverbs', 13, 4, 'لټ انسان چې هرڅه غواړي ورته نه رسیږي خو د خواري‌کښ انسان غوښتنې تل پوره کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_4.mp3', '', 1761754199, 1761754199),
(42788, 'Proverbs 13:5', 'Proverbs', 13, 5, 'نېک انسان له دروغو نه کرکه کوي خو بدکاره انسان شرم او رسوایي راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_5.mp3', '', 1761754199, 1761754199),
(42789, 'Proverbs 13:6', 'Proverbs', 13, 6, 'صداقت د پاک انسان لارې ټینګې ساتي خو ګناه بدکاره انسان له منځه وړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_6.mp3', '', 1761754199, 1761754199),
(42790, 'Proverbs 13:7', 'Proverbs', 13, 7, 'یو انسان خپل ځان شتمن ښایي خو هېڅ نه لري بل انسان خپل ځان غریب ښایي خو هرڅه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_7.mp3', '', 1761754199, 1761754199),
(42791, 'Proverbs 13:8', 'Proverbs', 13, 8, 'د یو انسان شتمني د هغه د ژوند کفاره ورکولای شي خو غریب انسان ته هېڅ ګواښ نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_8.mp3', '', 1761754199, 1761754199),
(42792, 'Proverbs 13:9', 'Proverbs', 13, 9, 'د نېکانو ژوند د لمر د رڼا په څېر ځلیږي خو د بدکارانو ډېوه مخ په مړه کېدو وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_9.mp3', '', 1761754199, 1761754199),
(42793, 'Proverbs 13:10', 'Proverbs', 13, 10, 'کبر او غرور حتمي جنجال پیدا کوي حکمت له هغه چا سره وي څوک چې لارښوونه مني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_10.mp3', '', 1761754199, 1761754199),
(42794, 'Proverbs 13:11', 'Proverbs', 13, 11, 'کوم مال دولت چې د باد په شان راځي نو د باد په شان فنا کیږي خو کومه شتمني چې ورو ورو لاسته راځي نوره هم زیاتیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_11.mp3', '', 1761754199, 1761754199),
(42795, 'Proverbs 13:12', 'Proverbs', 13, 12, 'کومه هیله چې نه پوره کیږي نو زړه ورسره ماتیږي خو کومه غوښتنه چې پوره کیږي د ژوندانه ونه ترې جوړیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_12.mp3', '', 1761754199, 1761754199),
(42796, 'Proverbs 13:13', 'Proverbs', 13, 13, 'څوک چې کلام سپک ګڼي د تاوان سره مخامخ کیږي خو څوک چې حکمونو ته په درنه سترګه ګوري انعام مومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_13.mp3', '', 1761754199, 1761754199),
(42797, 'Proverbs 13:14', 'Proverbs', 13, 14, 'د حکمت د خاوند تعلیم د ژوند سرچینه ده چې انسان د مرګ له دامونو څخه ژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_14.mp3', '', 1761754199, 1761754199),
(42798, 'Proverbs 13:15', 'Proverbs', 13, 15, 'پوهه او هوښیاري انسان ته عزت ورکوي خو د خیانت کوونکو لارې د کنډو کپرو په څېر سختې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_15.mp3', '', 1761754199, 1761754199),
(42799, 'Proverbs 13:16', 'Proverbs', 13, 16, 'ځیرک انسان د خپلې پوهې په وسیله کار کوي خو کم‌عقل سړی خپل جهالت ښکاره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_16.mp3', '', 1761754199, 1761754199),
(42800, 'Proverbs 13:17', 'Proverbs', 13, 17, 'بدکاره استازي د مصیبت سره مخامخ کیږي خو وفادار پیغام راوړونکی د شفا سبب ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_17.mp3', '', 1761754199, 1761754199),
(42801, 'Proverbs 13:18', 'Proverbs', 13, 18, 'څوک چې نصیحت له پامه غورځوي هغه به غریب او شرمنده شي خو څوک چې ملامتیا مني هغه به عزتمن شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_18.mp3', '', 1761754199, 1761754199),
(42802, 'Proverbs 13:19', 'Proverbs', 13, 19, 'کومه غوښتنه چې پوره کیږي نو روح خوشحالیږي خو کم‌عقلان د شرارت له لاس اخیستلو نه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_19.mp3', '', 1761754199, 1761754199),
(42803, 'Proverbs 13:20', 'Proverbs', 13, 20, 'د حکمت له خاوندانو سره مل شه نو حکیم به شې خو د کم‌عقلانو ملګرتیا سړي ته زیان رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_20.mp3', '', 1761754199, 1761754199),
(42804, 'Proverbs 13:21', 'Proverbs', 13, 21, 'بدي په ګناهکارانو پسې ګرځي خو نېکمرغي د نېکانو په برخه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_21.mp3', '', 1761754199, 1761754199),
(42805, 'Proverbs 13:22', 'Proverbs', 13, 22, 'ښه انسان خپلو لمسیانو ته میراث پرېږدي خو د ګناهکارانو شتمني نېک انسان ته پاتې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_22.mp3', '', 1761754199, 1761754199),
(42806, 'Proverbs 13:23', 'Proverbs', 13, 23, 'که د خوارانو خواره ځمکه ډېر خواړه ورکوي خو بې‌انصافه خلک دا هرڅه هم جارو کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_23.mp3', '', 1761754199, 1761754199),
(42807, 'Proverbs 13:24', 'Proverbs', 13, 24, 'څوک چې له خپل زوی نه د ادب لښته لېرې ساتي نو له هغه نه کرکه کوي خو څوک چې په سختۍ د هغه د اصلاح دپاره لار لټوي نو ورسره مینه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_24.mp3', '', 1761754199, 1761754199),
(42808, 'Proverbs 13:25', 'Proverbs', 13, 25, 'نېک انسان په مړه ګېډه ډوډۍ خوري خو د بدکارانو نس به تل وږی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs13_verse_25.mp3', '', 1761754199, 1761754199),
(42809, 'Proverbs 24:1', 'Proverbs', 24, 1, 'د بدکارانو سره بخیلي مه کوه او له هغوی سره د ملګرتیا تمه مه لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_1.mp3', '', 1761754199, 1761754199),
(42810, 'Proverbs 24:2', 'Proverbs', 24, 2, 'ځکه چې زړونه یې تل د تباهۍ نقشې جوړوي او شونډې یې د شرارت خبرې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_2.mp3', '', 1761754199, 1761754199);